//! Cross-language benchmark: reads Vortex files generated by Go and measures
//! Rust reader scan performance for direct comparison.
//!
//! Usage:
//!   cargo run --bin bench --release -- /tmp/vortex-bench

use std::env;
use std::fs;
use std::path::PathBuf;
use std::sync::LazyLock;
use std::time::{Duration, Instant};

use futures::StreamExt;
use futures::pin_mut;
use vortex_array::ToCanonical;
use vortex_array::expr::{select, root};
use vortex_array::session::ArraySession;
use vortex_array::expr::session::ExprSession;
use vortex_file::OpenOptionsSessionExt;
use vortex_io::session::{RuntimeSession, RuntimeSessionExt};
use vortex_layout::session::LayoutSession;
use vortex_session::VortexSession;

static SESSION: LazyLock<VortexSession> = LazyLock::new(|| {
    let mut session = VortexSession::empty()
        .with::<ArraySession>()
        .with::<LayoutSession>()
        .with::<ExprSession>()
        .with::<RuntimeSession>();
    vortex_file::register_default_encodings(&mut session);
    session.with_tokio()
});

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    let bench_dir = if args.len() > 1 {
        PathBuf::from(&args[1])
    } else {
        PathBuf::from("/tmp/vortex-bench")
    };

    if !bench_dir.exists() {
        eprintln!("Benchmark directory not found: {}", bench_dir.display());
        eprintln!("Run Go benchmark first:");
        eprintln!("  cd <vortex-go root>");
        eprintln!("  go test ./benchmark/ -run TestCrossLanguageBenchmark -v");
        std::process::exit(1);
    }

    let rt = tokio::runtime::Runtime::new()?;
    let _guard = rt.enter();

    println!();
    println!("╔════════════════════════════════════════════════════════════════════════════╗");
    println!("║                    Rust Reader Benchmark (same files as Go)                ║");
    println!("║  Schema: id:i64, value:f64, category:utf8  (3 columns)                     ║");
    println!("║  Mode: full decode (to_struct + to_primitive/to_varbinview per chunk)       ║");
    println!("╠════════════════════════════════════════════════════════════════════════════╣");
    println!();

    let cases: Vec<(&str, i64, usize)> = vec![
        ("100K", 100_000, 50),
        ("500K", 500_000, 20),
        ("1M", 1_000_000, 10),
    ];

    for (name, expected_rows, iters) in &cases {
        let path = bench_dir.join(format!("bench_{}.vtx", name));
        if !path.exists() {
            println!("  Skipping {} (file not found: {})", name, path.display());
            continue;
        }

        let data = fs::read(&path)?;
        let file_size = data.len();

        // Full scan with forced decode
        let (rows, full_avg) = bench_full_scan(&rt, &data, *iters)?;
        if rows != *expected_rows {
            eprintln!("  WARNING: expected {} rows, got {}", expected_rows, rows);
        }
        let throughput_mb = file_size as f64 / (1 << 20) as f64 / full_avg.as_secs_f64();
        let throughput_rows = rows as f64 / full_avg.as_secs_f64() / 1e6;

        // Lazy scan (just .len(), no decode) for comparison
        let (_, lazy_avg) = bench_lazy_scan(&rt, &data, *iters)?;
        let lazy_mb = file_size as f64 / (1 << 20) as f64 / lazy_avg.as_secs_f64();
        let lazy_rows = rows as f64 / lazy_avg.as_secs_f64() / 1e6;

        // Projected scan with decode (1/3 columns)
        let (_, proj_avg) = bench_projected_scan(&rt, &data, *iters)?;

        println!("┌─── {} ─── file: {}",
            name, fmt_bytes(file_size as i64));
        println!("│  Rust full decode:  {:>9}  ({}K rows, {:.0} MB/s, {:.1}M rows/s)",
            fmt_duration(full_avg), rows / 1000, throughput_mb, throughput_rows);
        println!("│  Rust lazy scan:    {:>9}  ({}K rows, {:.0} MB/s, {:.1}M rows/s)",
            fmt_duration(lazy_avg), rows / 1000, lazy_mb, lazy_rows);
        println!("│  Rust project 1/3:  {:>9}  ({:.1}× vs full)",
            fmt_duration(proj_avg),
            full_avg.as_secs_f64() / proj_avg.as_secs_f64());
        println!("└──────────────────────────────────────────────────────────────────");
        println!();
    }

    println!("╚════════════════════════════════════════════════════════════════════════════╝");
    Ok(())
}

/// Full scan with forced decode: to_struct + access every field as primitive/varbinview.
fn bench_full_scan(
    rt: &tokio::runtime::Runtime,
    data: &[u8],
    iters: usize,
) -> Result<(i64, Duration), Box<dyn std::error::Error>> {
    let mut total = Duration::ZERO;
    let mut rows = 0i64;

    for _ in 0..iters {
        let file = SESSION.open_options().open_buffer(data.to_vec())?;

        let t0 = Instant::now();
        let stream = file.scan()?.into_array_stream()?;
        pin_mut!(stream);

        let mut n = 0i64;
        rt.block_on(async {
            while let Some(result) = stream.next().await {
                let arr = result.unwrap();
                // Force full decode: struct → primitive fields + varbinview
                let s = arr.to_struct();
                let fields = s.unmasked_fields();
                let _col0 = fields[0].to_primitive();  // id: i64
                let _col1 = fields[1].to_primitive();  // value: f64
                let _col2 = fields[2].to_varbinview();  // category: utf8
                n += s.len() as i64;
            }
        });
        total += t0.elapsed();
        rows = n;
    }

    Ok((rows, total / iters as u32))
}

/// Lazy scan: just iterate chunks and check length (no decode).
fn bench_lazy_scan(
    rt: &tokio::runtime::Runtime,
    data: &[u8],
    iters: usize,
) -> Result<(i64, Duration), Box<dyn std::error::Error>> {
    let mut total = Duration::ZERO;
    let mut rows = 0i64;

    for _ in 0..iters {
        let file = SESSION.open_options().open_buffer(data.to_vec())?;

        let t0 = Instant::now();
        let stream = file.scan()?.into_array_stream()?;
        pin_mut!(stream);

        let mut n = 0i64;
        rt.block_on(async {
            while let Some(result) = stream.next().await {
                let arr = result.unwrap();
                n += arr.len() as i64;
            }
        });
        total += t0.elapsed();
        rows = n;
    }

    Ok((rows, total / iters as u32))
}

/// Projected scan with decode (1 column out of 3).
fn bench_projected_scan(
    rt: &tokio::runtime::Runtime,
    data: &[u8],
    iters: usize,
) -> Result<(i64, Duration), Box<dyn std::error::Error>> {
    let mut total = Duration::ZERO;
    let mut rows = 0i64;

    for _ in 0..iters {
        let file = SESSION.open_options().open_buffer(data.to_vec())?;

        let t0 = Instant::now();
        let stream = file.scan()?
            .with_projection(select(["id"], root()))
            .into_array_stream()?;
        pin_mut!(stream);

        let mut n = 0i64;
        rt.block_on(async {
            while let Some(result) = stream.next().await {
                let arr = result.unwrap();
                // Force decode of projected column
                let s = arr.to_struct();
                let _col0 = s.unmasked_fields()[0].to_primitive();
                n += s.len() as i64;
            }
        });
        total += t0.elapsed();
        rows = n;
    }

    Ok((rows, total / iters as u32))
}

fn fmt_bytes(b: i64) -> String {
    if b >= 1 << 20 {
        format!("{:.1} MB", b as f64 / (1 << 20) as f64)
    } else if b >= 1 << 10 {
        format!("{:.1} KB", b as f64 / (1 << 10) as f64)
    } else {
        format!("{} B", b)
    }
}

fn fmt_duration(d: Duration) -> String {
    let us = d.as_micros();
    if us >= 1_000_000 {
        format!("{:.2}s", d.as_secs_f64())
    } else if us >= 1000 {
        format!("{:.1}ms", us as f64 / 1000.0)
    } else {
        format!("{}µs", us)
    }
}
